<script setup lang="ts">
import { ref } from 'vue'
import { Check,Sparkles,Save } from 'lucide-vue-next'
import { post,kindName } from '../api'
import MathText from './MathText.vue'
const props=defineProps<{attempt:any}>(),emit=defineEmits(['changed'])
const a=ref(JSON.parse(JSON.stringify(props.attempt))),text=ref(a.value.student_answer),score=ref(a.value.final_score??a.value.suggested_score??''),feedback=ref(a.value.feedback||a.value.suggestion||''),busy=ref(false),error=ref('')
async function run(action:string,data:any={}){busy.value=true;error.value='';try{a.value=await post(`attempts/${a.value.id}/${action}/`,data);score.value=a.value.final_score??a.value.suggested_score??'';feedback.value=a.value.feedback||a.value.suggestion||'';emit('changed')}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><article class="question-card attempt-card"><header class="question-top"><div class="inline"><span class="question-number">{{a.item.label}}</span><span class="tag">{{kindName[a.item.snapshot.kind]}}</span><span class="status" :class="a.status">{{a.final_score===null?'待复核':'已定分'}}</span></div><strong v-if="a.final_score!==null" class="grade-score">{{a.final_score}}<small> / {{a.item.max_score}}</small></strong><span v-else class="muted">满分 {{a.item.max_score}} 分</span></header><div v-if="error" class="notice danger">{{error}}</div><MathText :text="a.item.snapshot.stem"/><div class="options-grid"><MathText v-for="option in a.item.snapshot.options" :text="option"/></div><div class="grading-columns"><section><h3>学生作答</h3><div class="source-images"><img v-for="r in a.regions" :src="`/api/pages/${r.page}/image/?bbox=${r.bbox.join(',')}`" alt="学生原始作答"/></div><textarea v-model="text" rows="4" :disabled="a.final_score!==null" placeholder="核对原图并确认识别文字；空白作答也需确认"/><button v-if="a.final_score===null" class="button secondary small" :disabled="busy" @click="run('recognize',{student_answer:text,confirmed:true})"><Check :size="15"/>{{a.recognition_confirmed?'更新并确认识别':'确认作答识别'}}</button><p v-else class="helper">已定分作答保留原始识别，可在右侧改分。</p></section><section class="reference-box"><h3>参考答案 · 已确认</h3><MathText :text="a.item.snapshot.answer"/><details><summary>解析与评分细则</summary><MathText :text="a.item.snapshot.explanation+'\n'+a.item.snapshot.rubric"/></details></section></div><div v-if="a.suggestion" class="notice neutral"><Sparkles :size="17"/><div><strong>批改建议{{a.suggested_score!==null?' · '+a.suggested_score+' 分':''}}</strong><p>{{a.suggestion}}</p></div></div><div class="grade-form"><label>最终得分<input v-model="score" type="number" min="0" :max="a.item.max_score" step="0.01" placeholder="待评分"/></label><label>评语 / 改分原因<input v-model="feedback" placeholder="记录解题思路与失分原因"/></label><div class="inline wrap"><button class="button secondary small" :disabled="busy||!a.recognition_confirmed||a.final_score!==null" @click="run('suggest')"><Sparkles :size="15"/>获取评分建议</button><button class="button primary small" :disabled="busy||!a.recognition_confirmed||score===''" @click="run('grade',{score,feedback,revision:a.revision})"><Save :size="15"/>{{a.final_score===null?'确认评分':'保存改分'}}</button></div></div><details v-if="a.history.length"><summary>评分历史（{{a.history.length}}）</summary><div v-for="h in a.history" class="history-line"><strong>{{h.score}} 分</strong><span>{{h.feedback||'无评语'}}</span><small>{{new Date(h.created_at).toLocaleString('zh-CN')}}</small></div></details></article></template>
